import{_ as e,o as n,c as r,ah as o}from"./chunks/framework.CfQBrslM.js";const i="/projects/AiArm/en/latest/assets/image2.Df6o_lVw.png",a="/projects/AiArm/en/latest/assets/image3.Bq5WC1b5.jpeg",s="/projects/AiArm/en/latest/assets/image2.gJjeS1pb.png",l="/projects/AiArm/en/latest/assets/image2.CtEyd2Kj.jpeg",d="/projects/AiArm/en/latest/assets/image3.DZ3m0xqg.png",c="/projects/AiArm/en/latest/assets/image5.DlBzyvfL.jpeg",g="/projects/AiArm/en/latest/assets/image6.XqIw_wbt.jpeg",h="/projects/AiArm/en/latest/assets/image7.DQrzucms.jpeg",_=JSON.parse('{"title":"1. Getting Ready","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.Getting Ready.md","filePath":"docs/1.Getting Ready.md"}'),p={name:"docs/1.Getting Ready.md"};function m(u,t,y,b,x,w){return n(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_1-getting-ready" tabindex="-1">1. Getting Ready <a class="header-anchor" href="#_1-getting-ready" aria-label="Permalink to &quot;1. Getting Ready&quot;">​</a></h1><h2 id="_1-1-aiarm-introduction" tabindex="-1">1.1 AiArm Introduction <a class="header-anchor" href="#_1-1-aiarm-introduction" aria-label="Permalink to &quot;1.1 AiArm Introduction&quot;">​</a></h2><h3 id="_1-1-1-description" tabindex="-1">1.1.1 Description <a class="header-anchor" href="#_1-1-1-description" aria-label="Permalink to &quot;1.1.1 Description&quot;">​</a></h3><ol><li><p>The AiArm robotic arm, combined with the base scene map and sensor kit, forms an intelligent educational robotic kit that simulates industrialization scene.</p></li><li><p>It is equipped with a WonderCam vision module, various sensor modules including an glowing ultrasonic module, LED dot matrix module, MP3 module and fan module. AiArm robotic arm enables color recognition, tag recognition, face recognition, QR code recognition and waste card recognition and the sensor modules provides feedback based on programs.</p></li><li><p>In terms of programming, it utilizes Scratch graphical programming and Python programming. It is designed to cater to entry-level programming users and provides a good understanding of program logic.</p></li></ol><img loading="lazy" height="829" width="1179" src="'+i+'" class="common_img" style="width:800px;"><h3 id="_1-1-2-packing-list" tabindex="-1">1.1.2 Packing List <a class="header-anchor" href="#_1-1-2-packing-list" aria-label="Permalink to &quot;1.1.2 Packing List&quot;">​</a></h3><ol><li>After receiving the package, you can first refer to the below packing list to check out if all accessories are complete according. If any missing parts are found, please contact our customer service for assistance.</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;"></th></tr></thead><tbody><tr><td style="text-align:center;">Product</td><td style="text-align:center;">Qty</td></tr><tr><td style="text-align:center;">AiArm robot arm</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Power adaptor/ 7.5V 7A</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Wireless handle</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">WonderCam vision module</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">USB cable</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Big base board</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Waste sorting base board</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Color sorting base board</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Waste sorting aluminium bar</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">Color sorting aluminium bar</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">Glowing ultrasonic sensor</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Dot matrix module</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">MP3 module (with SD card)</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Fan module</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">4PIN wire (50cm)</td><td style="text-align:center;">5</td></tr><tr><td style="text-align:center;">Sensor bracket</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Card reader</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Colored block (3<em>3</em>3cm)</td><td style="text-align:center;">1 set (red, green, blue per each)</td></tr><tr><td style="text-align:center;">Primary-color wooden block (4<em>4</em>4cm)</td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;">Primary-color wooden block (3<em>3</em>3cm)</td><td style="text-align:center;">3</td></tr></tbody></table><h3 id="_1-1-3-hardware-wiring" tabindex="-1">1.1.3 Hardware Wiring <a class="header-anchor" href="#_1-1-3-hardware-wiring" aria-label="Permalink to &quot;1.1.3 Hardware Wiring&quot;">​</a></h3><ol><li>The wiring diagram of the controller, expansion board and hardware modules is shown below:</li></ol><img loading="lazy" height="465" width="987" src="'+a+'" class="common_img" style="width:800px;"><h3 id="_1-1-4-learning-guide" tabindex="-1">1.1.4 Learning Guide <a class="header-anchor" href="#_1-1-4-learning-guide" aria-label="Permalink to &quot;1.1.4 Learning Guide&quot;">​</a></h3><ol><li><p><strong>Step 1</strong>: get to know AiArm robotic Arm</p></li><li><p><strong>Step 2</strong>: learn about how to use PC software to control the robotic arm and edit action</p></li><li><p><strong>Step 3</strong>: install programming software and learn how to write program.</p></li><li><p><strong>Step 4</strong>: get to know the driver module</p></li><li><p><strong>Step 5</strong>: the application WonderCam vision module</p></li><li><p><strong>Step 6</strong>: start game and grasp the programming logic</p></li><li><p><strong>Step 7</strong>: Understand the coordinate system of a robotic arm and control the robot arm using coordinates</p></li></ol><h2 id="_1-2-props-placement-and-assembly" tabindex="-1">1.2 Props Placement and Assembly <a class="header-anchor" href="#_1-2-props-placement-and-assembly" aria-label="Permalink to &quot;1.2 Props Placement and Assembly&quot;">​</a></h2><p>AiArm robotic arm advanced kit is equipped with a set of scene props to enable diverse functions. Having received the package, please get your robotic kit assembled according to the provided assembly tutorial. The main function of each area of the scene props is introduced below.<img loading="lazy" height="1225" width="1572" src="'+s+'" class="inline-icon"></p><ol><li><strong>Picking /recognizance Area</strong></li></ol><p>When the picking or recognition function is executed, AiArm robotic arm will place colored block, labeled wooden block or waste card into this area.</p><ol start="2"><li><strong>Sorting Area</strong></li></ol><p>When the sorting function is performed, AiArm robotic arm will pick and place the wooden block to the sorting area.</p><ol start="3"><li><strong>Sensor Integration Area</strong></li></ol><p>With the ultrasonic sensor, voice recognition module, MP3 module and dot matrix module assembled in this area, a variety of interaction games can be realized.</p><ol start="4"><li><strong>Waste Sorting Area</strong></li></ol><p>This area is equipped with four categories of trash bins, namely recyclable waste (blue), hazardous waste (red), kitchen waste (green), and other waste (gray), used for placing corresponding waste cards.</p><ol start="5"><li><strong>Props Placement Area</strong></li></ol><p>This area is used for placing the props that are not currently used in the game.</p><h2 id="_1-3-wireless-handle-control" tabindex="-1">1.3 Wireless Handle Control <a class="header-anchor" href="#_1-3-wireless-handle-control" aria-label="Permalink to &quot;1.3 Wireless Handle Control&quot;">​</a></h2><h3 id="_1-3-1-preparation" tabindex="-1">1.3.1 Preparation <a class="header-anchor" href="#_1-3-1-preparation" aria-label="Permalink to &quot;1.3.1 Preparation&quot;">​</a></h3><ol><li><strong>Step 1</strong>: Before tuning on robotic arm, please ensure that the handle receiver is connected to the controller on the robotic arm.</li></ol><img loading="lazy" height="520" width="693" src="'+l+'" class="common_img" style="width:800px;"><ol start="2"><li><p><strong>Step 2</strong>: Prepare two AAA batteries.</p></li><li><p><strong>Step 3</strong>: Take out the battery cover, and put the batteries into the battery slot. Please note that do not reverse the negative pole and positive pole of the battery.</p></li></ol><img loading="lazy" height="561" width="1499" src="'+d+'" class="common_img" style="width:800px;"><h3 id="_1-3-2-device-connection" tabindex="-1">1.3.2 Device Connection <a class="header-anchor" href="#_1-3-2-device-connection" aria-label="Permalink to &quot;1.3.2 Device Connection&quot;">​</a></h3><ol><li><p><strong>Step 1</strong>: Switch on the robotic arm.</p></li><li><p><strong>Step 2</strong>: Turn on the wireless handle. The two LEDS (red and green) on the handle will blink at the same time.</p></li><li><p><strong>Step 3</strong>: The robotic arm will automatically match with the wireless handle in few minutes, and the green LED keeps on.(If two lights blink after pressing Mode button,)</p></li><li><p><strong>Step 4</strong>: if you fail to connect, please switch off the robotic arm and wireless handle. Then start over from step 1.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Sleep mode: if the wireless handle isn’t connected with the robotic arm in 30 seconds, or has no operation in 5 minutes after connection, the wireless handle will enter the sleep mode. If you want to activate it, you can press the “START” button.</strong></p></div><h3 id="_1-3-3-mode-instruction" tabindex="-1">1.3.3 Mode Instruction <a class="header-anchor" href="#_1-3-3-mode-instruction" aria-label="Permalink to &quot;1.3.3 Mode Instruction&quot;">​</a></h3><ol><li><p>There are two modes for wireless handle control: action group mode and single servo mode. After the wireless handle is received, it defaults to the action group mode.</p></li><li><p><strong>Action group mode</strong>: press the buttons to perform the corresponding action.</p></li><li><p><strong>Single servo mode</strong>: press the buttons to control the forward and reverse rotation of each button on the robotic arm.</p></li><li><p>The way to switch two modes: first press <strong>“SELECT”</strong> key without releasing, and then press the <strong>“Start”</strong> key. After hearing a <strong>“Di”</strong> sound, the mode will switch to the action group mode and you can release <strong>“SELECT”</strong> button. If hearing a <strong>“Di Di”</strong> two beeps after releasing, the mode is the single servo mode.</p></li></ol><h3 id="_1-3-4-key-instruction" tabindex="-1">1.3.4 Key Instruction <a class="header-anchor" href="#_1-3-4-key-instruction" aria-label="Permalink to &quot;1.3.4 Key Instruction&quot;">​</a></h3><ol><li>The key instruction for the action group mode is shown in the below table.(For the combined keys, you need to first press the <strong>“SELECT”</strong> key without releasing, and then press the corresponding keys)</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;"></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Key</strong></td><td style="text-align:center;"><strong>Function</strong></td></tr><tr><td style="text-align:center;"><strong>START</strong></td><td style="text-align:center;"><strong>Run No.0 action</strong></td></tr><tr><td style="text-align:center;"><strong>↑</strong></td><td style="text-align:center;"><strong>Run No.1 action once</strong></td></tr><tr><td style="text-align:center;"><strong>↓</strong></td><td style="text-align:center;"><strong>Run No.2 action once</strong></td></tr><tr><td style="text-align:center;"><strong>←</strong></td><td style="text-align:center;"><strong>Run No.3 action once</strong></td></tr><tr><td style="text-align:center;"><strong>→</strong></td><td style="text-align:center;"><strong>Run No.4 action once</strong></td></tr><tr><td style="text-align:center;"><strong>△</strong></td><td style="text-align:center;"><strong>Run No.5 action once</strong></td></tr><tr><td style="text-align:center;"><strong>×</strong></td><td style="text-align:center;"><strong>Run No.6 action once</strong></td></tr><tr><td style="text-align:center;"><strong>◻</strong></td><td style="text-align:center;"><strong>Run No.7 action once</strong></td></tr><tr><td style="text-align:center;"><strong>○</strong></td><td style="text-align:center;"><strong>Run No.8 action once</strong></td></tr><tr><td style="text-align:center;"><strong>L1</strong></td><td style="text-align:center;"><strong>Run No.9 action once</strong></td></tr><tr><td style="text-align:center;"><strong>R1</strong></td><td style="text-align:center;"><strong>Run No.9 action once</strong></td></tr><tr><td style="text-align:center;"><strong>L2</strong></td><td style="text-align:center;"><strong>Run No.11 action once</strong></td></tr><tr><td style="text-align:center;"><strong>R2</strong></td><td style="text-align:center;"><strong>Run No.12 action once</strong></td></tr><tr><td style="text-align:center;"><strong>SELECT+△</strong></td><td style="text-align:center;"><strong>Run No.13 action once</strong></td></tr><tr><td style="text-align:center;"><strong>SELECT+×</strong></td><td style="text-align:center;"><strong>Run No.14 action once</strong></td></tr><tr><td style="text-align:center;"><strong>SELECT+◻</strong></td><td style="text-align:center;"><strong>Run No.15 action once</strong></td></tr><tr><td style="text-align:center;"><strong>SELECT+○</strong></td><td style="text-align:center;"><strong>Run No.16 action once</strong></td></tr><tr><td style="text-align:center;"><strong>SELECT+L1</strong></td><td style="text-align:center;"><strong>Run No.17 action once</strong></td></tr><tr><td style="text-align:center;"><strong>SELECT+R1</strong></td><td style="text-align:center;"><strong>Run No.18 action once</strong></td></tr></tbody></table><ol start="2"><li>The key instruction for the single servo mode is shown below:</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>In the single servo mode, you can press the “START” button to reset servo to the initial position.</strong></p></div><img loading="lazy" height="365" width="528" src="'+c+'" class="common_img" style="width:800px;"><img loading="lazy" height="278" width="437" src="'+g+'" class="common_img" style="width:800px;"><img loading="lazy" height="492" width="1011" src="'+h+'" class="common_img" style="width:800px;">',44)])])}const k=e(p,[["render",m]]);export{_ as __pageData,k as default};
